using System.IO;
using System.Text.Json;
namespace WoWItemEditor;
public partial class MainWindow
{
    private async Task VerifyChecklist(CatalogResult catalog)
    {
        static void Assert(bool value,string text){if(!value)throw new InvalidOperationException(text);}
        var set=catalog.Tooltips.Sets[523];var lookup=catalog.Items.ToDictionary(i=>i.Id);var head=lookup[22418];var hero=new CharacterSnapshot(new(99999,"Checklist fixture",10,7,false,0),[]);
        var drops=await SetChecklist.LoadDrops(set.Members);Assert(drops.Count==set.Members.Distinct().Count(),"Batch drop check includes members with no direct drops");
        var report=SetChecklist.Build(catalog,set,10,hero,drops);Assert(report.Any(c=>c.Check=="Equip requirements"&&c.Status=="Blocked"&&c.ItemId==head.Id),"Checklist links equip restrictions to the affected item");Assert(report.Count(c=>c.Check=="Drop assignment")==set.Members.Length,"Checklist includes a saved drop review for every member");Assert(report.Any(c=>c.Check=="Bonus threshold"&&c.Action=="Bonus"&&c.SpellId>0),"Bonus checks navigate by exact spell ID");
        var missing=catalog with{Items=catalog.Items.Where(i=>i.Id!=head.Id).ToList()};Assert(SetChecklist.Build(missing,set,60,null).Any(c=>c.Check=="Definition"&&c.Status=="Blocked"),"Missing set definitions are explicit blockers");
        var high=new CatalogItem(new(head.Fields,StringComparer.OrdinalIgnoreCase){["ItemLevel"]="101"});var unsafeCatalog=catalog with{Items=catalog.Items.Select(i=>i.Id==head.Id?high:i).ToList()};Assert(SetChecklist.Build(unsafeCatalog,set,60,null).Any(c=>c.Check=="Scaling & server rows"&&c.ItemId==head.Id&&c.Status=="Blocked"),"Checklist surfaces missing crash-sensitive server lookup rows");
        var duplicate=new CatalogItem(new(head.Fields,StringComparer.OrdinalIgnoreCase){["ID"]="2000000004"});var conflictCatalog=catalog with{Items=catalog.Items.Append(duplicate).ToList()};var conflictSet=set with{Members=[head.Id,duplicate.Id],Bonuses=[new(2,28844,0)]};var conflict=SetChecklist.Build(conflictCatalog,conflictSet,60,null);Assert(conflict.Any(c=>c.Check=="Slot conflict")&&conflict.Any(c=>c.Check=="Bonus threshold"&&c.Status=="Blocked"),"Bonus reachability uses compatible slots rather than raw item count");
        var unknown=SetChecklist.Build(catalog,set with{Bonuses=[new(2,1999999999,0)]},60,null);Assert(unknown.Any(c=>c.Check=="Spell data"&&c.Status=="Blocked"&&c.SpellId==1999999999),"Missing bonus spell data is not treated as valid");
        var refs=await ReferenceCatalog.LoadAsync();var source=await BonusSpells.LoadAsync(28844);var effect=source.Rows["spell_effect"].First(e=>TooltipData.Number(e,"EffectAura")==107&&TooltipData.Number(e,"EffectMiscValue1")==0);int effectId=TooltipData.Number(effect,"ID");var bonus=new BonusDraft(source,new(){[effectId]="150"});var description=refs.Explain(28844,new ContentRow(1,0,28844,2,Bonus:bonus));Assert(description.Contains(bonus.Description(refs.Data))&&description.Contains("flat",StringComparison.OrdinalIgnoreCase)&&description.Contains("points")&&description.Contains("2 equipped set pieces"),"Private bonus explanation resolves the draft and explains flat amount plus threshold");
        bool rejected=false;try{BonusValueRules.Validate(effect,"10001");}catch(InvalidOperationException){rejected=true;}Assert(rejected,"Explanations retain numeric safety limits");
        var periodic=new Dictionary<string,string>{["SpellID"]="28844",["Effect"]="6",["EffectAura"]="3",["EffectBasePointsF"]="25",["EffectAuraPeriod"]="2000",["ImplicitTarget1"]="6"};string periodicText=SpellExplanation.Effect(refs.Data,periodic);Assert(periodicText.Contains("25 points per tick")&&periodicText.Contains("2 seconds")&&periodicText.Contains("Selected enemy"),"Periodic explanation distinguishes per-tick amount, interval and target");
        var percentage=new Dictionary<string,string>{["Effect"]="6",["EffectAura"]="108",["EffectMiscValue1"]="0",["EffectBasePointsF"]="25"};Assert(SpellExplanation.Effect(refs.Data,percentage).Contains("25 percent"),"Percent modifiers are not described as flat damage");
        var proc=new ContentRow(1,1,28844,Trigger:2,Cooldown:1500,CategoryCooldown:-1,Condition:55);string procText=refs.Explain(28844,proc,true);Assert(procText.Contains("1.5 seconds")&&procText.Contains("not a 100%")&&procText.Contains("Condition 55")&&!procText.Contains("equipped set pieces"),"Proc explanation separates activation, cooldown, conditions and unknown effective chance");
        string options=ReferenceCatalog.ProcExplanation([new(){["ProcChance"]="15",["ProcRecovery"]="2000",["SpellProcsPerMinuteID"]="1"}],[],new(){[1]=new(){["BaseProcRate"]="2"}});Assert(options.Contains("15%")&&options.Contains("2 procs/minute")&&options.Contains("2 seconds"),"Stored chance, PPM and recovery are explained with units");
        string sentinel=ReferenceCatalog.ProcExplanation([new(){["ProcChance"]="101"}],[],new());Assert(sentinel.Contains("not a literal probability")&&!sentinel.Contains("101%"),"Out-of-range stored proc chance is not presented as an effective probability");
        var chainData=new TooltipData();chainData.Spells[10]=new(){["Name"]="Parent"};chainData.Spells[11]=new(){["Name"]="Child"};var chain=new BonusBlueprint(10,new([10,11],new(),[],"",[]),new(new()),new(){["spell_effect"]=[new(){["ID"]="100",["SpellID"]="10",["EffectIndex"]="0",["Effect"]="64",["EffectTriggerSpell"]="11"},new(){["ID"]="101",["SpellID"]="11",["EffectIndex"]="0",["Effect"]="2",["EffectBasePointsF"]="10"}]},new(),new(){[10]=new(){["Description"]="Triggers child"},[11]=new(){["Description"]="Deals $s1 damage"}});string chained=SpellExplanation.Describe(chainData,10,draft:new(chain,new(){[101]="42"}));Assert(chained.Contains("Stored effect amount: 42 points")&&!chained.Contains("Spell 200000000"),"Triggered child explanations use edited amounts without exposing synthetic spell IDs");
        var window=new SetChecklistWindow(catalog,523,60){Owner=this};window.Show();await window.Ready;Assert(window.Checks.Any(c=>c.Check=="Drop assignment")&&window.Checks.All(c=>c.Action!="Proc"||lookup[c.ItemId].ClassId==2),"Checklist renders and routes only weapon assignments to weapon proc editor");await RenderEditorWindow(window,"set-testing-checklist-preview");window.Close();
        var explanation=new EffectExplanationWindow("Set bonus · Revenge",refs.Explain(28844,new ContentRow(1,0,28844,2)),description){Owner=this};explanation.Show();await RenderEditorWindow(explanation,"bonus-explanation-preview");explanation.Close();var values=new BonusValueWindow(source,refs.Data,bonus){Owner=this};values.Show();await RenderEditorWindow(values,"bonus-value-meaning-preview");values.Close();
        var procEntry=refs.Procs.First(p=>p.EffectId is not null&&p.Trigger=="Chance on hit");var effectRow=refs.ItemEffects[procEntry.EffectId!.Value];int N(string key)=>TooltipData.Number(effectRow,key);var actualProc=new ContentRow(1,procEntry.EffectId.Value,procEntry.SpellId,Trigger:N("TriggerType"),Cooldown:N("CoolDownMSec"),CategoryCooldown:N("CategoryCoolDownMSec"),Charges:N("Charges"),Category:N("SpellCategoryID"),Specialization:N("ChrSpecializationID"),Condition:N("PlayerConditionID"));var procWindow=new EffectExplanationWindow("Weapon proc explanation · "+procEntry.Name,refs.Explain(procEntry.SpellId,actualProc,true),refs.Explain(procEntry.SpellId,actualProc with{Cooldown=1500},true)){Owner=this};procWindow.Show();await RenderEditorWindow(procWindow,"weapon-proc-explanation-preview");procWindow.Close();
        await File.WriteAllTextAsync("artifacts/checklist-explanation-verification.json",JsonSerializer.Serialize(new{checks="Equip restrictions; missing definitions; missing server rows; compatible-slot thresholds; missing spell; per-item direct drop reviews; exact editor targets; private draft bonus values; flat vs percentage amounts; periodic ticks and targets; proc cooldowns/conditions/chance/PPM; numeric caps preserved; rendered views; no game writes"},new JsonSerializerOptions{WriteIndented=true}));
    }
